            cid = min(unserved, key=lambda c: (remaining[c], dist(depot, c), c))
            route.append(cid)
            load += remaining[cid]
            unserved.remove(cid)
        routes.append(route)

    # Local search: route-level balancing by moving customers to reduce route count and travel.
    def route_load(rt):
        s = 0
        for c in rt:
            s += demand.get(c, 0)
        return s

    def route_cost(rt):
        if not rt:
            return 0
        c = dist(depot, rt[0])
        for i in range(len(rt) - 1):
            c += dist(rt[i], rt[i + 1])
        c += dist(rt[-1], depot)
        return c

    def best_reinsert_pos(rt, cid):
        if not rt:
            return 0, 0
        best_pos = 0
        best_delta = None
        base = route_cost(rt)
        for p in range(len(rt) + 1):
            prev = depot if p == 0 else rt[p - 1]
            nxt = depot if p == len(rt) else rt[p]
            delta = dist(prev, cid) + dist(cid, nxt) - dist(prev, nxt)
            if best_delta is None or delta < best_delta:
                best_delta = delta
                best_pos = p
        return best_pos, best_delta

    improved = True
    while improved:
        improved = False

        # Try to eliminate a route by relocating all its customers.
        r_idx = 0
        while r_idx < len(routes):
            rt = routes[r_idx]
            if len(rt) == 0:
                routes.pop(r_idx)
                improved = True
                continue
            can_remove = True
            temp_moves = []
            loads = [route_load(r) for r in routes]
            for cid in rt:
                placed = False
                best_j = None
                best_p = None
                best_delta = None
                for j in range(len(routes)):
                    if j == r_idx:
                        continue
                    if loads[j] + demand[cid] > capacity:
                        continue
                    pos, delta = best_reinsert_pos(routes[j], cid)
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_j = j
                        best_p = pos
                        placed = True
                if not placed:
                    can_remove = False
                    break
                temp_moves.append((cid, best_j, best_p))
                loads[best_j] += demand[cid]
            if can_remove and len(routes) > 1:
                # Apply moves in order, with indices adjusted by insertion order per route.
                moved_by_route = {}
                for cid, j, p in temp_moves:
                    moved_by_route.setdefault(j, []).append((p, cid))
                # remove current route first
                routes.pop(r_idx)
                # adjust indices after pop
                for j in sorted(moved_by_route.keys()):
                    inserts = sorted(moved_by_route[j], key=lambda x: x[0])
                    rr = routes[j]
                    shift = 0
                    for p, cid in inserts:
                        rr.insert(p + shift, cid)
                        shift += 1
                improved = True
                break
            r_idx += 1

        if improved:
            continue

        # 2-opt within each route.
        for r_idx in range(len(routes)):
            rt = routes[r_idx]
            n = len(rt)
            if n < 4:
                continue
            best_gain = 0
            best_i = None
            best_j = None
            base = route_cost(rt)
            for i in range(n - 2):
                a = depot if i == 0 else rt[i - 1]
                b = rt[i]
                for j in range(i + 1, n - 1):
                    c = rt[j]
                    d = depot if j == n - 1 else rt[j + 1]
                    gain = (dist(a, b) + dist(c, d)) - (dist(a, c) + dist(b, d))
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_i = i
                        best_j = j
            if best_i is not None:
                rt[best_i:best_j + 1] = rt[best_i:best_j + 1][::-1]
                improved = True
                break

    # Final repair: ensure all customers exactly once.
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    # Remove duplicates conservatively.
    if any(v != 1 for v in seen.values()) or len(seen) != len(customers):
        all_assigned = []
        for r in routes:
            all_assigned.extend(r)
        unique_routes = []
        used = set()
        for r in routes:
            nr = []
            for c in r:
                if c not in used:
                    nr.append(c)
                    used.add(c)
            if nr:
                unique_routes.append(nr)
        missing = [c for c in customers if c not in used]
        for cid in missing:
            placed = False
            best_j = None
            best_p = None
            best_delta = None
            for j in range(len(unique_routes)):
                if route_load(unique_routes[j]) + demand[cid] > capacity:
                    continue
                p, delta = best_reinsert_pos(unique_routes[j], cid)
                if best_delta is None or delta < best_delta:
                    best_delta = delta
                    best_j = j
                    best_p = p
                    placed = True
            if placed:
                unique_routes[best_j].insert(best_p, cid)
            else:
                unique_routes.append([cid])
        routes = unique_routes

    return routes
